import{_ as t,o as r,c as l,a5 as a}from"./chunks/framework.QnCkLuYX.js";const i="/assets/find-and-replace.BPJlYe71.png",n="/assets/filters-and-line-tools.B4uiAH7i.png",m=JSON.parse('{"title":"效率工具","description":"","frontmatter":{},"headers":[],"relativePath":"04-productivity-tools.md","filePath":"zh-CN/04-productivity-tools.md"}'),s={name:"04-productivity-tools.md"};function e(g,o,d,h,c,p){return r(),l("div",null,[...o[0]||(o[0]=[a('<h1 id="效率工具" tabindex="-1">效率工具 <a class="header-anchor" href="#效率工具" aria-label="Permalink to &quot;效率工具&quot;">​</a></h1><p>使用查找、筛选、批量替换和行操作减少重复工作。</p><h2 id="你可以在本页完成什么" tabindex="-1">你可以在本页完成什么 <a class="header-anchor" href="#你可以在本页完成什么" aria-label="Permalink to &quot;你可以在本页完成什么&quot;">​</a></h2><ul><li>精确查找并替换字幕文本。</li><li>用多种条件筛选和排序工作区。</li><li>批量断行、拆分、合并、新增或删除字幕行。</li><li>使用右键菜单和快捷键处理选择范围。</li></ul><h2 id="查找字幕内容" tabindex="-1">查找字幕内容 <a class="header-anchor" href="#查找字幕内容" aria-label="Permalink to &quot;查找字幕内容&quot;">​</a></h2><p>在表格工具栏的查找框输入内容，或按 <code>Ctrl+F</code>（macOS：<code>Command+F</code>）。匹配文字会在单元格中高亮。打开 <strong>高级查找 / 替换</strong>（<code>Ctrl+H</code>（macOS 也可使用；或点击按钮，避免 <code>Command+H</code> 隐藏窗口））后，可使用 <strong>上一个</strong>、<strong>下一个</strong> 在匹配间跳转。</p><p>查找从当前聚焦的匹配开始，而不是每次回到第一条。跳转会同步表格焦点和行选择。</p><h2 id="替换单个或全部匹配" tabindex="-1">替换单个或全部匹配 <a class="header-anchor" href="#替换单个或全部匹配" aria-label="Permalink to &quot;替换单个或全部匹配&quot;">​</a></h2><p><img src="'+i+'" alt="高级查找替换面板，包含匹配选项和替换操作"></p><ol><li>输入 <strong>查找内容</strong> 和 <strong>替换为</strong>。</li><li>根据需要启用： <ul><li><strong>仅搜索译文</strong></li><li><strong>区分大小写</strong></li><li><strong>使用正则表达式</strong></li><li><strong>匹配整个单元格</strong></li></ul></li><li>点击 <strong>替换</strong> 修改当前匹配，或点击 <strong>全部替换</strong>。</li></ol><p>启用 <strong>筛选结果</strong> 后，表格只显示匹配行。替换会进入撤销历史；如果查询或选项变化导致当前行不再匹配，焦点会移动到仍可见的有效行。</p><p>正则表达式无效时，面板会显示错误且不会执行替换。查找内容中的前导空格和纯空格查询会按原样保留。</p><h2 id="使用批量替换规则" tabindex="-1">使用批量替换规则 <a class="header-anchor" href="#使用批量替换规则" aria-label="Permalink to &quot;使用批量替换规则&quot;">​</a></h2><p><strong>批量替换</strong>用于反复应用一组替换对：</p><ol><li>添加“查找/替换为”规则。</li><li>调整规则顺序；规则从上到下依次应用，前一条结果会进入下一条。</li><li>点击 <strong>应用到译文</strong>。</li><li>查看本次修改行数。</li></ol><p>规则可从 <code>bad_words.csv</code> 导入或导出，并在应用级保存。多个窗口同时修改规则时，应用会要求选择重新加载、覆盖或取消，避免静默覆盖另一窗口的设置。</p><h2 id="筛选需要处理的字幕" tabindex="-1">筛选需要处理的字幕 <a class="header-anchor" href="#筛选需要处理的字幕" aria-label="Permalink to &quot;筛选需要处理的字幕&quot;">​</a></h2><p><img src="'+n+'" alt="表格工具栏中的长行、高 CPS、条件筛选和行工具"></p><p>快速筛选：</p><ul><li>点击 <strong>长行</strong>，只显示超过项目行长阈值的译文。</li><li>点击 <strong>高 CPS</strong>，只显示超过最大 CPS 的行。</li></ul><p>条件筛选：</p><ol><li>点击 <strong>显示筛选</strong>。</li><li>选择字段、条件和筛选值。</li><li>添加多条规则。</li><li>用 <strong>规则逻辑</strong> 选择所有规则都满足（AND）或任一规则满足（OR）。</li></ol><p>文本字段支持包含、不包含、等于、不等于、为空和非空；数值字段还支持大于、不小于、小于和不大于。</p><p>筛选只改变可见行，不删除数据。开启或关闭筛选时，多选范围会清理，只保留有效焦点行。</p><h2 id="排序和调整表格视图" tabindex="-1">排序和调整表格视图 <a class="header-anchor" href="#排序和调整表格视图" aria-label="Permalink to &quot;排序和调整表格视图&quot;">​</a></h2><ul><li>点击列标题切换升序、降序和默认顺序。</li><li>拖动列边界调整列宽。</li><li>在设置中启用 <strong>显示隐藏列</strong> 查看元数据列。</li><li>点击 <strong>重置视图</strong> 清除筛选和临时视图。</li><li>点击顶部 <strong>重置布局</strong> 恢复列宽。</li></ul><p>排序和筛选后，复制、粘贴、全选和行工具均以当前可见行顺序为准。</p><h2 id="批量选择字幕" tabindex="-1">批量选择字幕 <a class="header-anchor" href="#批量选择字幕" aria-label="Permalink to &quot;批量选择字幕&quot;">​</a></h2><p>可以通过行标记、矩形范围、<code>Ctrl</code>（macOS：<code>Command</code>） 多范围或左上角全选框选择目标。工具栏会显示“已选”数量。</p><p>右键菜单提供 <strong>剪切</strong>、<strong>复制</strong>、<strong>粘贴</strong>、<strong>清空单元格</strong>、<strong>断行</strong>、<strong>拆分</strong>、<strong>合并</strong>、<strong>添加行</strong>和 <strong>删除选中</strong>。不可安全执行的命令会被禁用。</p><h2 id="为字幕自动换行" tabindex="-1">为字幕自动换行 <a class="header-anchor" href="#为字幕自动换行" aria-label="Permalink to &quot;为字幕自动换行&quot;">​</a></h2><p><strong>断行</strong>在译文中寻找接近中点的空格并插入字幕换行符；它仍保持一条字幕行和原时间范围。</p><ol><li>选择一行或多行。</li><li>点击 <strong>断开选中行</strong>，或在右键菜单选择 <strong>断行</strong>。</li><li>查看完成摘要中的成功、无变化和失败数量。</li></ol><p>没有合适空格、已经换行或超出项目行长限制时，原行会保留并计入摘要。</p><h2 id="拆分字幕行" tabindex="-1">拆分字幕行 <a class="header-anchor" href="#拆分字幕行" aria-label="Permalink to &quot;拆分字幕行&quot;">​</a></h2><p><strong>拆分</strong>把一条字幕变成两条或多条：</p><ol><li>选择目标行。</li><li>点击 <strong>拆分选中行</strong>。</li><li>应用优先按现有换行拆分，否则选择合适的空格。</li><li>新行按文本长度比例分配原字幕时间。</li></ol><p>原行的集数和字幕元数据会保留。时间无效、没有可拆位置或不满足行长要求时不会修改该行。</p><h2 id="合并字幕行" tabindex="-1">合并字幕行 <a class="header-anchor" href="#合并字幕行" aria-label="Permalink to &quot;合并字幕行&quot;">​</a></h2><ol><li>选择同一集、时间顺序相邻的两行或多行。</li><li>点击 <strong>合并选中行</strong>。</li><li>如果时间严格连续，直接合并。</li><li>如果存在间隙，审查提示后选择 <strong>仍然合并</strong> 或取消。</li></ol><p>合并后的时间从第一行开始到最后一行结束，文本字段用字幕换行连接。不同集或不相邻的可见行不能合并。</p><h2 id="新增和删除字幕行" tabindex="-1">新增和删除字幕行 <a class="header-anchor" href="#新增和删除字幕行" aria-label="Permalink to &quot;新增和删除字幕行&quot;">​</a></h2><ul><li><strong>添加行</strong>：在当前焦点行下方插入一条空译文行，并保留必要的行结构。</li><li><strong>删除选中</strong>：删除选中的可见行。完成后焦点移动到下一条仍存在的可见行；没有下一条时移动到上一条。</li></ul><p>新增、拆分、合并和删除都会进入撤销历史，并触发质量和拼写结果更新。</p><h2 id="使用右键菜单和快捷键" tabindex="-1">使用右键菜单和快捷键 <a class="header-anchor" href="#使用右键菜单和快捷键" aria-label="Permalink to &quot;使用右键菜单和快捷键&quot;">​</a></h2><p>在单元格或选区内右键可打开紧凑操作菜单。右键选区外的单元格会先把它设为当前选择。文本输入框仍使用系统原生右键菜单。</p><p>常用快捷键见<a href="./01-getting-started.html#查看快捷键和操作帮助">开始使用</a>。</p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><ul><li><strong>行工具不可用</strong>：确认已选择可见行；合并至少需要两条同集相邻行。</li><li><strong>粘贴没有影响隐藏行</strong>：这是预期行为，筛选时只向当前可见行粘贴。</li><li><strong>断行和拆分结果不同</strong>：断行保留一条字幕；拆分会生成多条字幕并重新分配时间。</li><li><strong>批量替换规则冲突</strong>：选择重新加载可保留磁盘版本；只有明确选择覆盖才会写入当前窗口版本。</li></ul>',49)])])}const b=t(s,[["render",e]]);export{m as __pageData,b as default};
